CREATE TABLE public.seo_audits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), site_url text NOT NULL CHECK(length(site_url) BETWEEN 4 AND 500), robots jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(robots)='object' AND length(robots::text)<=20000), sitemap jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(sitemap)='object' AND length(sitemap::text)<=40000), pages jsonb NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(pages)='array' AND length(pages::text)<=200000), findings jsonb NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(findings)='array' AND length(findings::text)<=100000), page_count integer NOT NULL DEFAULT 0 CHECK(page_count BETWEEN 0 AND 100), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), CHECK(org_id = public.ws_org(workspace_id)));
GRANT SELECT, INSERT ON public.seo_audits TO authenticated; GRANT ALL ON public.seo_audits TO service_role;
ALTER TABLE public.seo_audits ENABLE ROW LEVEL SECURITY;
CREATE POLICY seo_audits_read ON public.seo_audits FOR SELECT TO authenticated USING(public.has_workspace_role(workspace_id,'viewer'));
CREATE POLICY seo_audits_create ON public.seo_audits FOR INSERT TO authenticated WITH CHECK(public.has_workspace_role(workspace_id,'member') AND created_by=auth.uid());
CREATE INDEX seo_audits_ws_idx ON public.seo_audits(workspace_id, created_at DESC);